FUNCTION solve_partial_fraction():
    // Given equation: G/(x+5) + H/(x^2-4x) = (x^2-2x+10)/(x^3+x^2-20x)
    // Factor denominator: x^3 + x^2 - 20x = x(x+5)(x-4)

    // Set up equation after common denominator:
    // G*x*(x-4) + H*(x+5) = x^2 - 2x + 10

    // Expand left side: G*x^2 - 4G*x + H*x + 5H = x^2 - 2x + 10

    // Compare coefficients:
    // x^2 coefficient: G = 1
    // x coefficient: H - 4G = -2  
    // Constant term: 5H = 10

    G = 1
    H = 10 / 5  // Solve 5H = 10
    H = H - 4*G  // Solve H - 4G = -2 (verification)

    RETURN H / G

