function solve_congruence():
    a = 27
    b = 17
    m = 40

    // Step 1: Find modular inverse of a modulo m using Extended GCD
    gcd, x, y = extended_gcd(a, m)
    if gcd != 1:
        return null  // No solution exists
    inverse_a = x % m

    // Step 2: Compute smallest positive solution
    smallest_a = (b * inverse_a) % m

    // Step 3: Compute second smallest solution
    second_smallest_a = smallest_a + m

    // Step 4: Return sum
    return smallest_a + second_smallest_a

function extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

