function count_trailing_zeros_in_base_11(n):
    // Count the highest power of 11 that divides n!
    // This is equivalent to counting how many multiples of 11 are in {1, 2, ..., n}
    count = 0
    power_of_11 = 11
    while power_of_11 <= n:
        count += floor(n / power_of_11)
        power_of_11 *= 11
    return count

