function solve():
    // Define work rates (fraction of house per hour)
    good_rate = 1 / 12
    bad_rate = 1 / 36

    // Total work = 1 house
    total_work = 1

    // Available good workers
    good_workers = 3

    // Work completed by good workers in 3 hours
    good_work = good_workers * good_rate * 3

    // Remaining work after good workers
    remaining_work = total_work - good_work

    // If no remaining work, no bad workers needed
    if remaining_work <= 0:
        return 0

    // Time available for bad workers = 3 hours
    time_available = 3

    // Calculate bad workers needed using rate × time = work
    bad_workers_needed = ceil(remaining_work / (bad_rate * time_available))

    return bad_workers_needed

