FUNCTION count_fruit_baskets(apples, oranges):
    // Count ways to choose apples (0 to apples) using stars and bars: C(apples+1, 1)
    apple_ways = C(apples + 1, 1)

    // Count ways to choose oranges (0 to oranges) using stars and bars: C(oranges+1, 1)  
    orange_ways = C(oranges + 1, 1)

    // Total combinations including empty basket
    total = apple_ways * orange_ways

    // Subtract empty basket case
    RETURN total - 1

FUNCTION C(n, k):
    // Binomial coefficient calculation
