    // Step 3: For each z, solve f(x) = z
    all_x_solutions = {}
    FOR each y IN y_values:
        FOR each z IN all_z_solutions[y]:
            // Solve f(x) = z => x^2/4 + x - 3 = z
            // => x^2/4 + x - (3 + z) = 0
            // => x^2 + 4x - 4(3 + z) = 0
            x_solutions = solve_quadratic(1, 4, -4*(3 + z))
            all_x_solutions[z] = x_solutions

